</tbody></table></div><div class="totals"><p>Subtotal: <b>£<?php echo e(number_format($quote['subtotal_pence']/100,2)); ?></b></p><p>Delivery: <b>£<?php echo e(number_format($quote['delivery_pence']/100,2)); ?></b></p><p>Estimated VAT on goods: <b>£<?php echo e(number_format($quote['vat_pence']/100,2)); ?></b></p><h2>Total: £<?php echo e(number_format($quote['grand_total_pence']/100,2)); ?></h2><a href="<?php echo e(route('checkout.form')); ?>" class="btn">Proceed to checkout →</a></div></div>
